const FURNACE_LIVE_POLL_MS = 5000;

function isBoxFurnaceDevice(name) {
  return typeof name === 'string' && /^BFT_box_[abcd]$/i.test(name);
}

function humanizeAttributeName(name) {
  if (ATTRIBUTE_LABELS[name]) {
    return ATTRIBUTE_LABELS[name];
  }
  return String(name || '')
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (ch) => ch.toUpperCase());
}

function looksLikeUnixTimestamp(value) {
  return typeof value === 'number' && Number.isFinite(value) && value > 1e9 && value < 1e12;
}

function formatAttributeScalar(name, value) {
  if (value === null || value === undefined || value === '') {
    return '—';
  }
  if (typeof value === 'boolean') {
    return value ? 'Yes' : 'No';
  }
  if (name === 'battery_percentage' && typeof value === 'number') {
    return `${value} %`;
  }
  if (name === 'no_progress_age_s' && typeof value === 'number') {
    return `${value} s`;
  }
  if (name === 'battery_checked_at' || looksLikeUnixTimestamp(value)) {
    const ms = value > 1e12 ? value : value * 1000;
    const date = new Date(ms);
    if (!Number.isNaN(date.getTime())) {
      return date.toLocaleString();
    }
  }
  if (typeof value === 'number' && Number.isFinite(value)) {
    return String(value);
  }
  return String(value);
}

function formatAttributeObject(name, value) {
  if (Array.isArray(value)) {
    if (value.length === 0) {
      return '—';
    }
    if (value.every((entry) => entry === null || ['string', 'number', 'boolean'].includes(typeof entry))) {
      return value.map((entry) => formatAttributeScalar(name, entry)).join(', ');
    }
    return value.map((entry) => (
      typeof entry === 'object' ? JSON.stringify(entry) : formatAttributeScalar(name, entry)
    )).join('; ');
  }
  if (name === 'battery_policy' && value && typeof value === 'object') {
    const parts = [];
    if (value.working_floor != null) parts.push(`work ≥ ${value.working_floor}%`);
    if (value.resume_at != null) parts.push(`resume ≥ ${value.resume_at}%`);
    if (value.alarm_at != null) parts.push(`alarm ≤ ${value.alarm_at}%`);
    if (value.hard_floor != null) parts.push(`hard floor ${value.hard_floor}%`);
    return parts.length > 0 ? parts.join(' · ') : '—';
  }
  const entries = Object.entries(value);
  if (entries.length === 0) {
    return '—';
  }
  if (entries.every(([, entry]) => entry === null || ['string', 'number', 'boolean'].includes(typeof entry))) {
    return entries
      .map(([key, entry]) => `${humanizeAttributeName(key)} ${formatAttributeScalar(key, entry)}`)
      .join(' · ');
  }
  // Nested structure: keep readable without a monospace dump.
  try {
    return JSON.stringify(value);
  } catch (err) {
    return String(value);
  }
}

function formatAttributeDisplay(name, value) {
  if (value !== null && typeof value === 'object') {
    return formatAttributeObject(name, value);
  }
  return formatAttributeScalar(name, value);
}

function FurnaceLiveStatus({ deviceName, open }) {
  const [liveStatus, setLiveStatus] = React.useState(null);
  const [error, setError] = React.useState('');
  const [loading, setLoading] = React.useState(false);

  React.useEffect(() => {
    if (!open) {
      return undefined;
    }
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      try {
        const response = await execute_device_control_command(
          deviceName,
          'get_live_status',
          null,
          {},
        );
        if (cancelled) {
          return;
        }
        if (response.status !== 'success') {
          throw new Error(response.errors || 'Failed to read furnace status.');
        }
        setLiveStatus(response.data?.result || null);
        setError('');
      } catch (err) {
        if (!cancelled) {
          setError(err.message || 'Failed to read furnace status.');
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };
    load();
    const intervalId = window.setInterval(load, FURNACE_LIVE_POLL_MS);
    return () => {
      cancelled = true;
      window.clearInterval(intervalId);
    };
  }, [open, deviceName]);

  if (!open) {
    return null;
  }

  const temperature = liveStatus?.temperature;
  const setpoint = liveStatus?.setpoint;
  const programMode = liveStatus?.program_mode;
  const doorOpen = liveStatus?.door_open;
  const isRunning = liveStatus?.is_running;

  return (
    <div style={{ marginBottom: 12 }}>
      <Typography variant="subtitle2" gutterBottom>Furnace live status</Typography>
      {error ? (
        <Alert severity="warning" sx={{ py: 0.5 }}>{error}</Alert>
      ) : (
        <Stack spacing={0.5}>
          <Typography variant="body2">
            <b>Temperature:</b>{' '}
            {loading && liveStatus == null ? '…' : (temperature == null ? '—' : `${temperature} °C`)}
          </Typography>
          <Typography variant="body2">
            <b>Setpoint:</b>{' '}
            {loading && liveStatus == null ? '…' : (setpoint == null ? '—' : `${setpoint} °C`)}
          </Typography>
          <Typography variant="body2">
            <b>Program:</b>{' '}
            {loading && liveStatus == null ? '…' : (programMode || '—')}
          </Typography>
          <Typography variant="body2">
            <b>Door:</b>{' '}
            {loading && liveStatus == null ? '…' : (doorOpen == null ? '—' : (doorOpen ? 'Open' : 'Closed'))}
          </Typography>
          <Typography variant="body2">
            <b>Heating / too hot:</b>{' '}
            {loading && liveStatus == null ? '…' : (isRunning == null ? '—' : (isRunning ? 'Yes' : 'No'))}
          </Typography>
        </Stack>
      )}
    </div>
  );
}


const DEFAULT_LOG_HEIGHT = 220;

function DeviceLogPane({ deviceName, open }) {
  const [lines, setLines] = React.useState([]);
  const [available, setAvailable] = React.useState(false);
  const [reason, setReason] = React.useState(null);
  const [height, setHeight] = React.useState(DEFAULT_LOG_HEIGHT);
  const preRef = React.useRef(null);
  const stickToBottom = React.useRef(true);

  useEffect(() => {
    if (!open) {
      setHeight(DEFAULT_LOG_HEIGHT);
      return undefined;
    }
    let cancelled = false;
    const load = () => {
      get_device_verbose_log(deviceName, 200).then((data) => {
        if (cancelled || !data) {
          return;
        }
        setAvailable(Boolean(data.available));
        setReason(data.reason || null);
        setLines(data.lines || []);
      });
    };
    load();
    const interval = setInterval(load, 1000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [open, deviceName]);

  useEffect(() => {
    const el = preRef.current;
    if (el && stickToBottom.current) {
      el.scrollTop = el.scrollHeight;
    }
  }, [lines]);

  const onScroll = (event) => {
    const el = event.target;
    stickToBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < 24;
  };

  const onResizeStart = (event) => {
    event.preventDefault();
    const startY = event.clientY;
    const startHeight = height;
    const onMove = (moveEvent) => {
      const next = startHeight + (moveEvent.clientY - startY);
      setHeight(Math.max(DEFAULT_LOG_HEIGHT, next));
    };
    const onUp = () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  };

  let emptyMessage = 'Waiting for the first log line…';
  if (!available && reason === 'no_file') {
    emptyMessage = 'No log file yet. It appears once this device is next called.';
  }

  const text = lines.length > 0 ? lines.join('\n') : emptyMessage;

  return (
    <div className="device-detail-log">
      <Typography variant="subtitle2" gutterBottom>Live log</Typography>
      <div className="device-live-log-wrap">
        <pre
          ref={preRef}
          className={lines.length > 0 ? 'device-live-log' : 'device-live-log empty'}
          style={{ height }}
          onScroll={onScroll}
        >
          {text}
        </pre>
        <div
          className="device-live-log-resizer"
          role="separator"
          aria-orientation="horizontal"
          aria-label="Drag to make the live log taller"
          onMouseDown={onResizeStart}
        />
      </div>
    </div>
  );
}


function DeviceAttributes({ attributes }) {
  const entries = Object.entries(attributes || {}).filter(([name]) => {
    // Connection bookkeeping is shown via ConnectionNotice on the row.
    return ![
      "disabled",
      "disabled_reason",
      "connection_status",
      "connection_error",
      "connection_waiting_seconds",
      "connection_blocked_on_user_input",
      "connection_user_input_prompt",
    ].includes(name);
  });
  if (entries.length === 0) {
    return (
      <Typography variant="caption" sx={{ color: "#9e9e9e" }}>
        This device does not publish any attributes. Add names to its `dashboard_attributes` to show them here.
      </Typography>
    );
  }
  return (
    <Stack spacing={0.5}>
      {entries.map(([name, value]) => (
        <Typography key={name} variant="body2">
          <b>{humanizeAttributeName(name)}:</b>{' '}
          {formatAttributeDisplay(name, value)}
        </Typography>
      ))}
    </Stack>
  );
}


function Row({ device, hoverForId }) {
  const [open, setOpen] = React.useState(false);
  const attributeCount = Object.keys(device.attributes || {}).length;

  const rowColor = () => {
    switch (device.status) {
      case "OCCUPIED":
        return DEVICE_ACCENTS.occupiedBg;
      case "MANUAL_CONTROL":
        return DEVICE_ACCENTS.manualControlBg;
      case "ERROR":
        return DEVICE_ACCENTS.errorBg;
      case "PAUSE_REQUESTED":
        return DEVICE_ACCENTS.pauseRequestedBg;
      case "PAUSED":
        return DEVICE_ACCENTS.pausedBg;
      case "DISABLED":
        return DEVICE_ACCENTS.disabledBg;
      case "CONNECTING":
        return DEVICE_ACCENTS.connectingBg;
      default:
        return "#ffffff";
    }
  }

  const textColor = (task_status) => {
    switch (task_status) {
      case "OCCUPIED":
        return DEVICE_ACCENTS.occupiedText;
      case "MANUAL_CONTROL":
        return DEVICE_ACCENTS.manualControlText;
      case "ERROR":
        return DEVICE_ACCENTS.errorText;
      case "PAUSE_REQUESTED":
        return DEVICE_ACCENTS.pauseRequestedText;
      case "PAUSED":
        return DEVICE_ACCENTS.pausedText;
      case "DISABLED":
        return DEVICE_ACCENTS.disabledText;
      case "CONNECTING":
        return DEVICE_ACCENTS.connectingText;
      default:
        return "#000000";
    }
  }

  const subtextColor = (task_status) => {
    switch (task_status) {
      case "OCCUPIED":
        return DEVICE_ACCENTS.occupiedText;
      case "MANUAL_CONTROL":
        return DEVICE_ACCENTS.manualControlText;
      case "ERROR":
        return DEVICE_ACCENTS.errorText;
      case "PAUSE_REQUESTED":
        return DEVICE_ACCENTS.pauseRequestedText;
      case "PAUSED":
        return DEVICE_ACCENTS.pausedText;
      case "DISABLED":
        return DEVICE_ACCENTS.disabledText;
      case "CONNECTING":
        return DEVICE_ACCENTS.connectingText;
      default:
        return "#9e9e9e";
    }
  }

  const permanentlyDisabled = Boolean(device.attributes?.disabled);
  const connectionStatus = device.attributes?.connection_status;
  const notConnected = connectionStatus === "connecting" || connectionStatus === "failed";

  const PauseButton = ({ pause_state, device_name, permanently_disabled, connecting }) => {
    // Fixed width so Pause ↔ Release (and Cancel Pause Request) never resize the column.
    const buttonSx = { width: "100%", minWidth: 0, whiteSpace: "nowrap" };
    if (permanently_disabled) {
      return (
        <Typography variant="caption" sx={{ color: DEVICE_ACCENTS.disabledText }}>
          Disabled
        </Typography>
      );
    }
    // The pause on a connecting device is applied by alabos, not an operator, so offering
    // "Release" here would imply it is the way to make the device usable. It is not.
    if (connecting) {
      return (
        <Typography variant="caption" sx={{ color: DEVICE_ACCENTS.connectingText }}>
          Connecting…
        </Typography>
      );
    }
    switch (pause_state) {
      case "RELEASED":
        return (
          <Button
            variant="contained"
            color="error"
            sx={buttonSx}
            onClick={() => { request_device_pause(device_name) }}
          >
            Pause
          </Button>
        )
      case "REQUESTED":
        return (
          <Button
            variant="contained"
            color="primary"
            sx={buttonSx}
            onClick={() => release_device_pause(device_name)}
          >
            Cancel Pause Request
          </Button>
        )
      case "PAUSED":
        return (
          <Button
            variant="contained"
            color="primary"
            sx={buttonSx}
            onClick={() => release_device_pause(device_name)}
          >
            Release
          </Button>
        )
    }
  }



  return (
    <React.Fragment key={device.name}>
      <TableRow
        sx={{
          '& > *': { borderBottom: attributeCount > 0 && open ? 'unset' : undefined },
          bgcolor: rowColor(device.status),
        }}
      >
        <TableCell align="center" padding="none" width="48">
          <IconButton
            aria-label="show device details"
            size="small"
            onClick={() => setOpen(!open)}
            sx={{ color: textColor(device.status) }}
          >
            {open ? <KeyboardArrowUpIcon /> : <KeyboardArrowDownIcon />}
          </IconButton>
        </TableCell>
        <TableCell component="th" scope="row">
          <Typography
            variant="body1"
            sx={{
              color: textColor(device.status),
            }}
          >
            {device.name}
          </Typography>
          <Typography variant="caption"
            sx={{ color: subtextColor(device.status) }}
          >{device.type}</Typography>
        </TableCell>
        <TableCell align="center">
          <span
            className="status-chip"
            style={{
              backgroundColor: rowColor(device.status) === "#ffffff" ? "#eeeeee" : rowColor(device.status),
              color: textColor(device.status) === "#000000" ? "#5f5f5f" : textColor(device.status),
            }}
          >
            {STATUS_LABELS[device.status] || device.status}
          </span>
        </TableCell>
        <TableCell align="center" size="small">
          <OccupiedSamplePositions samples={device.samples} />
        </TableCell>
        <TableCell align="left" width="45%" >
          <ConnectionNotice attributes={device.attributes} />
          {!notConnected &&
            <Typography variant="caption" sx={{
              color: textColor(device.status),
              whiteSpace: "pre-wrap",
              display: '-webkit-box',
              overflow: 'auto',
              WebkitBoxOrient: 'vertical',
              WebkitLineClamp: 3,
            }}>{device.message}</Typography>
          }
        </TableCell>
        <TableCell
          align="center"
          sx={{ width: 220, minWidth: 220, maxWidth: 220, px: 1 }}
        >
          <PauseButton
            pause_state={device.pause_status}
            device_name={device.name}
            permanently_disabled={permanentlyDisabled}
            connecting={connectionStatus === "connecting"}
          />
        </TableCell>
      </TableRow>
      <TableRow sx={{ bgcolor: rowColor(device.status) }}>
        <TableCell style={{ paddingBottom: 0, paddingTop: 0 }} colSpan={6}>
          <Collapse in={open} timeout="auto" unmountOnExit>
            <div className="device-detail-split">
              <div className="device-detail-state">
                <Typography variant="subtitle2" gutterBottom>Device state</Typography>
                {isBoxFurnaceDevice(device.name) && (
                  <FurnaceLiveStatus deviceName={device.name} open={open} />
                )}
                <DeviceAttributes attributes={device.attributes} />
              </div>
              <DeviceLogPane deviceName={device.name} open={open} />
            </div>
          </Collapse>
        </TableCell>
      </TableRow>
    </React.Fragment>
  );
}



function OccupiedSamplePositions({ samples }) {
  let total_samples = 0;
  for (const occupied of Object.values(samples || {})) {
    total_samples += occupied.length;
  }
  return <Typography variant="body1">{total_samples}</Typography>;
}

function Devices({ hoverForId }) {
  const [devices, setDevices] = React.useState([]);
  const [hideIdleDevices, setHideIdleDevices] = React.useState(false);
  const [labReady, setLabReady] = React.useState(null);
  const [labReadyLabel, setLabReadyLabel] = React.useState('');

  useEffect(() => {
    const applyStatus = (data) => {
      const incoming = data?.devices || [];
      setDevices((previous) => mergeDeviceOrder(previous, incoming));
      if (data && Object.prototype.hasOwnProperty.call(data, 'lab_ready')) {
        setLabReady(Boolean(data.lab_ready));
        setLabReadyLabel(data.lab_ready_label || '');
      }
    };

    get_status().then(applyStatus);

    const interval = setInterval(() => {
      get_status().then(applyStatus);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const DisplayDeviceRowFilter = (row) => {
    if (row.status != "IDLE") {
      return true
    }
    for (let samples of Object.values(row.samples)) {
      if (samples.length > 0) {
        return true
      }
    }
    return false
  }

  const FilteredDevices = (hideIdle) => {
    if (hideIdle) {
      return devices.filter(DisplayDeviceRowFilter)
    } else {
      return devices
    }
  }


  return (
    <>
      <Stack
        direction="row"
        spacing={2}
        alignItems="center"
        sx={{ padding: "0px 16px", mb: 1, flexWrap: "wrap" }}
      >
        <FormControl component="fieldset" variant="standard">
          <FormControlLabel
            control={
              <Switch
                checked={hideIdleDevices}
                onChange={() => setHideIdleDevices(!hideIdleDevices)}
                name="Hide idle devices with no samples"
              />
            }
            label="Hide idle devices with no samples"
          />
        </FormControl>
        {labReady !== null && (
          <Chip
            size="small"
            label={labReady ? (labReadyLabel || 'Lab ready') : (labReadyLabel || 'Lab not ready')}
            color={labReady ? 'success' : 'warning'}
            variant="outlined"
          />
        )}
      </Stack>
      <TableContainer style={{ height: "100%" }} component={Paper}>
        <StyledDevicesDiv>
          <Table stickyHeader aria-label="device table">
            <TableHead>
              <TableRow>
                <TableCell padding="none" width="48" />
                <TableCell><b>Name</b></TableCell>
                <TableCell align="center"><b>Status</b></TableCell>
                <TableCell align="center"><b>Samples</b></TableCell>
                <TableCell align="center" width="45%"><b>Message</b></TableCell>
                <TableCell
                  align="center"
                  sx={{ width: 220, minWidth: 220, maxWidth: 220 }}
                >
                  Pause
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {FilteredDevices(hideIdleDevices).map((device) => (
                <Row key={device.name} device={device} hoverForId={hoverForId} />
              ))}
            </TableBody>
          </Table>
        </StyledDevicesDiv>
      </TableContainer>
    </>
  )
}

export default Devices;
